        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;

    const p = new Int32Array(N + 1);
    const head = new Int32Array(N + 1);
    const to = new Int32Array(N + 1);
    const next = new Int32Array(N + 1);
    let edgeCount = 0;

    for (let i = 2; i <= N; i++) {
        p[i] = nextInt();
        edgeCount++;
        to[edgeCount] = i;
        next[edgeCount] = head[p[i]];
        head[p[i]] = edgeCount;
    }

    const Q = nextInt();

    // Binary Lifting
    const LOGN = 18;
    const up = [];
    for (let j = 0; j < LOGN; j++) {
        up.push(new Int32Array(N + 1));
    }

    for (let i = 2; i <= N; i++) {
        up[0][i] = p[i];
    }
    up[0][1] = 0;

    for (let j = 1; j < LOGN; j++) {
        const upJ = up[j];
        const upPrev = up[j - 1];
        for (let i = 1; i <= N; i++) {
            const anc = upPrev[i];
            upJ[i] = anc === 0 ? 0 : upPrev[anc];
        }
    }

    function getKthAncestor(node, k) {
        for (let j = 0; j < LOGN; j++) {
            if ((k & (1 << j)) !== 0) {
                node = up[j][node];
                if (node === 0) break;
            }
        }
        return node;
    }

    // Euler Tour iterativa para evitar estouro de pilha
    const inTime = new Int32Array(N + 1);
    const outTime = new Int32Array(N + 1);
    let timer = 0;

    const stack = new Int32Array(N + 1);
    const edgePtr = new Int32Array(N + 1);
    let top = 0;
    stack[0] = 1;
    edgePtr[1] = head[1];
    inTime[1] = ++timer;

    while (top >= 0) {
        const u = stack[top];
        const e = edgePtr[u];
        if (e !== 0) {
            edgePtr[u] = next[e];
            const v = to[e];
            inTime[v] = ++timer;
            edgePtr[v] = head[v];
            top++;
            stack[top] = v;
        } else {
            outTime[u] = timer;
            top--;
        }
    }

    // Segment Tree para Range Assignment e Point Query
    const lazy = new Int32Array(4 * N + 1);

    function push(node) {
        if (lazy[node] !== 0) {
            lazy[node << 1] = lazy[node];
            lazy[(node << 1) | 1] = lazy[node];
            lazy[node] = 0;
        }
    }

    function update(node, l, r, ql, qr, val) {
        if (ql <= l && r <= qr) {
            lazy[node] = val;
            return;
        }
        push(node);
        const mid = (l + r) >> 1;
        if (ql <= mid) {
            update(node << 1, l, mid, ql, qr, val);
        }
        if (qr > mid) {
            update((node << 1) | 1, mid + 1, r, ql, qr, val);
        }
    }

