        if (l === r) {
            return lazy[node];
        }
        push(node);
        const mid = (l + r) >> 1;
        if (pos <= mid) {
            return query(node << 1, l, mid, pos);
        } else {
            return query((node << 1) | 1, mid + 1, r, pos);
        }
    }

    let out = '';
    const CHUNK_SIZE = 65536;

    for (let q = 0; q < Q; q++) {
        const type = nextInt();
        if (type === 1) {
            const v = nextInt();
            const k = nextInt();

            const A = query(1, 1, N, inTime[v]);
            let ans = 0;
            if (A === 0) {
                ans = getKthAncestor(v, k);
            } else {
                if (k === 1) {
                    ans = A;
                } else {
                    ans = getKthAncestor(A, k - 1);
                }
            }

            out += ans + '\n';
            if (out.length >= CHUNK_SIZE) {
                process.stdout.write(out);
                out = '';
            }
        } else {
            const v = nextInt();
            const A = query(1, 1, N, inTime[v]);
            // A reestruturação só é eficaz se nenhum ancestral de v foi reestruturado
            if (A === 0) {
